SELECT CASE WHEN city IN ('Berlin', 'London') THEN 'priority' ELSE 'other' END AS city_group, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(STDDEV(rating), 2) AS stddev_rating FROM suppliers WHERE city IN ('London', 'Tokyo') AND rating >= 3.4 AND country IN ('US', 'SG', 'DE') GROUP BY CASE WHEN city IN ('Berlin', 'London') THEN 'priority' ELSE 'other' END, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END HAVING ROUND(STDDEV(rating), 2) >= 27 ORDER BY city_group, rating_bucket LIMIT 50;
